/* drawing helpers of this lesson (prefix CM_ so nothing clashes with the engine) */
const CM_F='font-family="Nunito Sans, sans-serif"';
const CM_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${CM_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const CM_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const CM_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}" ${o.ex||''}/>`;
const CM_pts=(f,t0,t1,x0,x1,yc,k,n)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return p};
const CM_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=160,ex='')=>`<polyline points="${CM_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round" ${ex}/>`;
const CM_area=(f,t0,t1,x0,x1,yc,k,col,op=.25,n=120,ex='')=>`<polygon points="${x0},${yc} ${CM_pts(f,t0,t1,x0,x1,yc,k,n).join(' ')} ${x1},${yc}" fill="${col}" fill-opacity="${op}" stroke="${col}" stroke-width="3" stroke-linejoin="round" ${ex}/>`;
const CM_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return CM_L(x1,y1,x2-h*.6*Math.cos(a),y2-h*.6*Math.sin(a),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const CM_brk=(x1,x2,y,col,d=10)=>`<polyline points="${x1},${y-d} ${x1},${y} ${x2},${y} ${x2},${y-d}" fill="none" stroke="${col}" stroke-width="3" stroke-linejoin="round"/>`;
const CM_dot=(x,y,r,col)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${col}" stroke="#FFFFFF" stroke-width="2"/>`;
const CM_sub=b=>`<tspan	baseline-shift="-0.2em"	font-size="72%">${b}</tspan>`;      /* tabs, not spaces: lines that wrap never break the tag */
const CM_MUT='#5C6577', CM_GRY='#ADB5BD';
const CM_Rb=`R${CM_sub('b')}`, CM_Rs=`R${CM_sub('s')}`, CM_Es=`E${CM_sub('s')}`, CM_Eb=`E${CM_sub('b')}`, CM_N0=`N${CM_sub('0')}`, CM_Pb=`P${CM_sub('b')}`, CM_Ps=`P${CM_sub('s')}`, CM_Tb=`T${CM_sub('b')}`, CM_FC=`f${CM_sub('c')}`;
const CM_sinc=u=>Math.abs(u)<1e-9?1:Math.sin(Math.PI*u)/(Math.PI*u);
const CM_db=(v,lo)=>Math.max(lo,10*Math.log10(Math.max(v,1e-12)));
/* one-sided power spectra against f/Rb, each normalised to 1 at f = 0 (rectangular-pulse QPSK; MSK) */
const CM_psdQ=x=>CM_sinc(2*x)**2;
const CM_psdM=x=>{const d=1-16*x*x;return Math.abs(d)<1e-6?(Math.PI/4)**2:(Math.cos(2*Math.PI*x)/d)**2};
/* MFSK union bound Ps <= (M-1) Q(sqrt(k Eb/N0)) at Eb/N0 = 8 dB (6.310), worked in python:
   M=2: 5.99e-3, M=4: 5.73e-4, M=8: 4.75e-5, M=16: 3.80e-6 */
const CM_MF=[[2,5.99e-3,'6.0 × 10⁻³'],[4,5.73e-4,'5.7 × 10⁻⁴'],[8,4.75e-5,'4.8 × 10⁻⁵'],[16,3.80e-6,'3.8 × 10⁻⁶']];
/* MSK phase path for bits b (each bit Tb wide): returns theta in quarter turns at time t (units of Tb) */
const CM_th=(b,t)=>{let th=0;for(let i=0;i<b.length;i++){const d=b[i]?1:-1;if(t<=i+1)return th+d*(t-i);th+=d}return th};

